def get_color(x, y):
    # Using color index 3*x' + y' for unique identification of the 9 states
    return 3 * (x % 3) + (y % 3)

# Check all neighbors of (0, 0)
center_color = get_color(0, 0)

neighbor_colors = []
for dx in [-1, 0, 1]:
    for dy in [-1, 0, 1]:
        if dx == 0 and dy == 0:
            continue

        color = get_color(0 + dx, 0 + dy)
        neighbor_colors.append(color)

print(f"Color of (0, 0): {center_color}")
print(f"Colors of neighbors: {neighbor_colors}")
print(f"Are all neighbor colors distinct from the center color? {all(c != center_color for c in neighbor_colors)}")
print(f"Are all neighbor colors distinct from each other? {len(set(neighbor_colors)) == len(neighbor_colors)}")
